/**
 * WordPress REST API 客户端
 */

/**
 * Debug 日志（只在调试模式显示）
 */
function debugLog(...args: unknown[]) {
  const debugLevel = localStorage.getItem('zeroy_debug');
  if (debugLevel === '1') {
    console.log('[ZeroY API]', ...args);
  }
}

/**
 * REST API Rewrite 错误
 * 当 /wp-json/ 路径 404 但 ?rest_route= 可用时抛出
 */
export class RestApiRewriteError extends Error {
  readonly isRewriteError = true;

  constructor() {
    super(
      '服务器 URL 重写规则未正确配置。WordPress REST API 的 /wp-json/ 路径无法访问。'
    );
    this.name = 'RestApiRewriteError';
  }
}

interface RequestConfig extends RequestInit {
  params?: Record<string, any>;
}

// 顶层正则表达式常量
const TRAILING_SLASH_REGEX = /\/$/;
const COOKIE_REGEX = /cookie/i;
const NONCE_REGEX = /nonce/i;

class ApiClient {
  private baseUrl: string;
  private nonce: string;
  private refreshing: Promise<string> | null = null;

  constructor() {
    // Resolve API URL and force same-origin to avoid nonce failures
    const rawApiUrl =
      window.zeroyEditor?.apiUrl ||
      window.zeroySettings?.apiUrl ||
      window.zeroyAdmin?.apiUrl ||
      '/wp-json/zeroy/v1';

    // Normalize to a same-origin base path. If rawApiUrl is absolute and on a
    // different origin, drop the origin and keep only the pathname so fetch
    // remains same-origin and includes auth cookies.
    try {
      const url = new URL(rawApiUrl, window.location.origin);
      const sameOrigin = url.origin === window.location.origin;
      const normalized = sameOrigin ? url.href : url.pathname;
      this.baseUrl = normalized.replace(TRAILING_SLASH_REGEX, '');
    } catch {
      this.baseUrl = String(rawApiUrl).replace(TRAILING_SLASH_REGEX, '');
    }

    // Use the appropriate nonce based on the context
    this.nonce =
      window.zeroyEditor?.nonce ||
      window.zeroySettings?.nonce ||
      window.zeroyAdmin?.nonce ||
      '';
  }

  private buildConfig(base: RequestInit, override?: RequestInit): RequestInit {
    const defaultConfig: RequestInit = {
      headers: {
        'Content-Type': 'application/json',
        'X-WP-Nonce': this.nonce,
      },
      credentials: 'same-origin',
      cache: 'no-store',
    };
    return {
      ...defaultConfig,
      ...(override || base),
      headers: {
        ...defaultConfig.headers,
        ...(((override || base).headers as any) || {}),
      },
    } as RequestInit;
  }

  private fetchOnce(url: URL, base: RequestInit, override?: RequestInit) {
    return fetch(url.toString(), this.buildConfig(base, override));
  }

  /**
   * 处理请求错误，检测特定错误类型并抛出相应异常
   */
  private async handleRequestError(
    response: Response,
    url: URL
  ): Promise<never> {
    const error = await response.json().catch(() => ({
      message: response.statusText,
    }));

    // Debug 日志 - 详细错误信息
    console.error('[ZeroY API] 请求失败:', {
      url: url.toString(),
      status: response.status,
      statusText: response.statusText,
      error,
      errorCode: error?.code,
      errorMessage: error?.message,
      errorData: error?.data,
    });

    // 检测 rewrite 问题：404 且 URL 包含 /wp-json/
    if (response.status === 404 && url.pathname.includes('/wp-json/')) {
      const isRewriteIssue = await this.detectRewriteIssue(url);
      if (isRewriteIssue) {
        throw new RestApiRewriteError();
      }
    }

    throw new Error(error.message || `HTTP error! status: ${response.status}`);
  }

  /**
   * 检测是否是 rewrite 规则问题
   * 通过尝试 ?rest_route= 备用路径来判断
   */
  private async detectRewriteIssue(originalUrl: URL): Promise<boolean> {
    try {
      // 从 /wp-json/zeroy/v1/xxx 提取路由路径
      const wpJsonIndex = originalUrl.pathname.indexOf('/wp-json/');
      if (wpJsonIndex === -1) {
        return false;
      }

      const routePath = originalUrl.pathname.slice(
        wpJsonIndex + '/wp-json'.length
      );

      // 构建 ?rest_route= 格式的 URL
      const fallbackUrl = new URL(window.location.origin);
      fallbackUrl.searchParams.set('rest_route', routePath);

      debugLog('检测 rewrite 问题，尝试备用路径:', fallbackUrl.toString());

      const response = await fetch(fallbackUrl.toString(), {
        method: 'GET',
        credentials: 'same-origin',
        headers: {
          'X-WP-Nonce': this.nonce,
        },
      });

      // 如果备用路径可以访问（不是 404），说明是 rewrite 问题
      const isRewriteIssue = response.status !== 404;

      if (isRewriteIssue) {
        console.warn(
          '[ZeroY API] 检测到服务器 rewrite 规则问题：\n' +
            '  - /wp-json/ 路径返回 404\n' +
            '  - ?rest_route= 路径可正常访问\n' +
            '  - 请检查服务器的 .htaccess 或 nginx 配置'
        );
      }

      return isRewriteIssue;
    } catch (e) {
      debugLog('rewrite 检测失败:', e);
      return false;
    }
  }

  private shouldRetryNonce(status: number, payload: any): boolean {
    if (status !== 403) {
      return false;
    }
    const msg = payload?.message || '';
    const code = payload?.code || '';
    return (
      code === 'rest_cookie_invalid_nonce' ||
      COOKIE_REGEX.test(msg) ||
      NONCE_REGEX.test(msg)
    );
  }

  private unwrapResponse(json: any) {
    if (json && json.success === true && Object.hasOwn(json, 'data')) {
      const keys = Object.keys(json).filter(
        (k) => k !== 'success' && k !== 'data' && k !== 'message'
      );
      if (keys.length > 0) {
        return json;
      }
      if (json.message) {
        return { ...json.data, message: json.message };
      }
      return json.data;
    }
    return json;
  }

  private async request<T>(
    endpoint: string,
    config: RequestConfig = {}
  ): Promise<T> {
    const { params, ...fetchConfig } = config;

    // 构建 URL - 确保正确的路径连接
    const cleanEndpoint = endpoint.startsWith('/')
      ? endpoint.slice(1)
      : endpoint;
    const url = new URL(
      `${this.baseUrl}/${cleanEndpoint}`,
      window.location.origin
    );
    if (params) {
      for (const key of Object.keys(params)) {
        url.searchParams.append(key, params[key]);
      }
    }

    // 首次请求
    let response = await this.fetchOnce(url, fetchConfig);

    // 如遇 403 且疑似 nonce 过期，尝试刷新并重试一次
    if (!response.ok) {
      let payload: any = null;
      try {
        payload = await response.clone().json();
      } catch {
        // ignore
      }
      if (this.shouldRetryNonce(response.status, payload)) {
        try {
          await this.refreshNonce();
          response = await this.fetchOnce(url, fetchConfig);
        } catch {
          // ignore; will throw below
        }
      }
    }

    if (!response.ok) {
      await this.handleRequestError(response, url);
    }

    const json = await response.json();
    return this.unwrapResponse(json);
  }

  // Public: allow other modules to proactively refresh the nonce
  refreshNonce(): Promise<string> {
    if (this.refreshing) {
      return this.refreshing;
    }
    this.refreshing = (async () => {
      try {
        // First try REST endpoint (works when nonce not fully invalidated by caches)
        try {
          const nonceUrl = new URL(
            `${this.baseUrl}/auth/nonce`,
            window.location.origin
          );
          const res = await fetch(nonceUrl.toString(), {
            method: 'GET',
            credentials: 'same-origin',
            headers: {
              'X-WP-Nonce': this.nonce || '',
            },
          });
          if (res.ok) {
            const json = await res.json();
            const newNonce = json?.data?.nonce || json?.nonce || '';
            if (newNonce) {
              this.nonce = newNonce;
              return this.nonce;
            }
          }
        } catch {
          // fall through to AJAX fallback
        }

        // Fallback to admin-ajax (does not require REST nonce)
        const ajaxUrl =
          (window as any)?.zeroySettings?.ajaxUrl ||
          (window as any)?.ajaxurl ||
          '/wp-admin/admin-ajax.php';
        const res2 = await fetch(ajaxUrl, {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `action=${encodeURIComponent('zeroy_refresh_rest_nonce')}`,
        });
        const json2 = await res2.json();
        const newNonce2 = json2?.data?.nonce || json2?.nonce || '';
        if (newNonce2) {
          this.nonce = newNonce2;
        }
        return this.nonce;
      } finally {
        this.refreshing = null;
      }
    })();
    return this.refreshing;
  }

  // GET 请求
  get<T>(endpoint: string, params?: Record<string, any>): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'GET',
      params,
    });
  }

  // POST 请求
  post<T>(endpoint: string, data?: any, config?: RequestConfig): Promise<T> {
    // 如果是 FormData，不要 stringify，也不要设置 Content-Type（浏览器会自动设置 boundary）
    const isFormData = data instanceof FormData;

    // Debug 日志（只在详细模式显示）
    if (isFormData) {
      debugLog('POST FormData 请求:', {
        endpoint,
        isFormData: true,
        formDataKeys: data ? Array.from(data.keys()) : [],
      });
    } else {
      debugLog('POST JSON 请求:', {
        endpoint,
        data,
      });
    }

    const requestConfig: RequestConfig = {
      method: 'POST',
      body: isFormData ? data : JSON.stringify(data),
      ...config,
    };

    // 如果是 FormData，移除 Content-Type header（让浏览器自动设置）
    if (isFormData && requestConfig.headers) {
      const headers = requestConfig.headers as Record<
        string,
        string | undefined
      >;
      headers['Content-Type'] = undefined;
      console.log('[ZeroY API] 移除 Content-Type header（FormData 自动设置）');
    }

    return this.request<T>(endpoint, requestConfig);
  }

  // PUT 请求
  put<T>(endpoint: string, data?: any): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PUT',
      body: JSON.stringify(data),
    });
  }

  // DELETE 请求
  delete<T>(endpoint: string): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'DELETE',
    });
  }
}

export const apiClient = new ApiClient();
