import { authClient } from './auth-client';
import { apiClient } from './client';

export interface Settings {
  enabled: boolean;
  base_url: string;
  api_key: string;
  model: string;
  post_types: string[];
  production_mode: boolean;
  api_token: string;
  additional_context?: string;
  design_system_html?: string;
  submissions?: any;
  [key: string]: any;
}

export interface PostType {
  name: string;
  label: string;
}

export interface SettingsResponse {
  settings: Settings;
  postTypes: PostType[];
}

export const settingsApi = {
  /**
   * 获取设置
   */
  get(): Promise<SettingsResponse> {
    return apiClient.get<SettingsResponse>('/settings');
  },

  /**
   * 更新设置
   */
  update(settings: Partial<Settings>): Promise<{
    message: string;
    settings: Settings;
    unchanged?: boolean;
  }> {
    return apiClient.post('/settings', settings);
  },

  /**
   * 重置设置
   */
  reset(): Promise<{
    message: string;
    settings: Settings;
  }> {
    return apiClient.post('/settings/reset');
  },

  /**
   * 验证 API Token (直接客户端验证，不经过 WordPress)
   */
  async verifyToken(token: string): Promise<{
    valid: boolean;
    message: string;
    error?: string;
    details?: {
      requestOrigin: string;
      allowedWebsite: string;
    };
  }> {
    const result = await authClient.verifyToken(token);
    return {
      valid: result.valid,
      message: result.message,
      error: result.error,
      details: result.details,
    };
  },
};
