const DEV_LOCAL = 'dev=1';
const DEV_STAGING = 'dev=2';

export const getServerApiBase = (): string => {
  const href = typeof window !== 'undefined' ? window.location.href : '';
  if (href.includes(DEV_LOCAL)) {
    return 'http://localhost:5173/api';
  }
  if (href.includes(DEV_STAGING)) {
    return 'https://zeroy-staging.yansir.workers.dev/api';
  }
  return 'https://www.zeroy.app/api';
};
