/**
 * Remote Notification Banner Component
 *
 * Displays remote notifications from zeroy server
 */

import { Bell, Info, X } from 'lucide-react';
import type React from 'react';
import type {
  NotificationPriority,
  RemoteNotification,
} from '@/api/notifications';

interface RemoteNotificationBannerProps {
  notification: RemoteNotification;
  onDismiss: (id: string) => void;
}

/**
 * Get background color classes based on priority
 */
function getBackgroundClasses(priority: NotificationPriority): string {
  const baseClasses = 'border-l-4';

  if (priority === 'high') {
    return `${baseClasses} bg-amber-50 border-amber-500`;
  }

  return `${baseClasses} bg-blue-50 border-blue-400`;
}

export const RemoteNotificationBanner: React.FC<
  RemoteNotificationBannerProps
> = ({ notification, onDismiss }) => {
  const { id, priority, title, message } = notification;

  return (
    <div
      className={`relative rounded-r-lg p-4 shadow-sm ${getBackgroundClasses(priority)}`}
    >
      <div className="flex items-start gap-3">
        {/* Icon */}
        <div className="flex-shrink-0 pt-0.5">
          <Info
            className={`h-5 w-5 ${priority === 'high' ? 'text-amber-500' : 'text-blue-500'}`}
          />
        </div>

        {/* Content */}
        <div className="min-w-0 flex-1">
          {title && (
            <h4 className="mb-1 font-medium text-gray-900 text-sm">{title}</h4>
          )}
          <p className="text-gray-700 text-sm">{message}</p>
        </div>

        {/* Dismiss button */}
        <button
          aria-label="关闭通知"
          className="flex-shrink-0 rounded-md p-1 text-gray-400 transition-colors hover:bg-white/50 hover:text-gray-600"
          onClick={() => onDismiss(id)}
          type="button"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      {/* High priority indicator */}
      {priority === 'high' && (
        <div className="absolute top-2 right-8">
          <span className="inline-flex items-center gap-1 rounded-full bg-red-100 px-2 py-0.5 font-medium text-red-700 text-xs">
            <Bell className="h-3 w-3" />
            重要
          </span>
        </div>
      )}
    </div>
  );
};
