import { getServerApiBase } from './server';

/**
 * Direct Auth Client - Client-side token verification without WordPress proxy
 */

export interface TokenVerifyResponse {
  valid: boolean;
  error?: string;
  message: string;
  details?: {
    requestOrigin: string;
    allowedWebsite: string;
  };
  userId?: string;
  tokenId?: number;
  websiteUrl?: string;
}

/**
 * Direct auth client that bypasses WordPress proxy
 */
export class AuthClient {
  /**
   * Verify API token directly with the external server
   * @param token - The token to verify (optional, can be null)
   * @returns Token verification response
   */
  async verifyToken(token?: string | null): Promise<TokenVerifyResponse> {
    const url = `${getServerApiBase()}/verify-token`;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        credentials: 'omit', // Don't send cookies for CORS
        mode: 'cors', // Explicitly set CORS mode
        body: token ? JSON.stringify({ token }) : 'null',
      });

      if (!response.ok) {
        // Handle non-200 responses
        const errorData = await response.json().catch(() => null);
        return {
          valid: false,
          error: 'http_error',
          message:
            errorData?.message || `HTTP error! status: ${response.status}`,
        };
      }

      const data: TokenVerifyResponse = await response.json();
      return data;
    } catch (error) {
      // Handle network errors, CORS errors, etc.
      console.error('Token verification failed:', error);

      // Check if it's a CORS error
      if (error instanceof TypeError && error.message.includes('fetch')) {
        return {
          valid: false,
          error: 'cors_error',
          message:
            'Cross-origin request blocked. Please check CORS configuration.',
        };
      }

      return {
        valid: false,
        error: 'network_error',
        message: 'Failed to verify token due to network error',
      };
    }
  }
}

// Export singleton instance
export const authClient = new AuthClient();
