/**
 * Remote Notifications Container
 *
 * Container component that fetches and displays remote notifications
 */

import type React from 'react';
import { useRemoteNotifications } from '@/hooks/use-remote-notifications';
import { RemoteNotificationBanner } from './remote-notification-banner';

interface RemoteNotificationsContainerProps {
  /**
   * Filter notifications by priority
   * If not specified, shows all notifications
   */
  priorityFilter?: ('high' | 'normal')[];

  /**
   * Maximum number of notifications to display
   * @default 3
   */
  maxDisplay?: number;

  /**
   * Additional CSS class
   */
  className?: string;
}

export const RemoteNotificationsContainer: React.FC<
  RemoteNotificationsContainerProps
> = ({ priorityFilter, maxDisplay = 3, className = '' }) => {
  const { notifications, dismiss } = useRemoteNotifications({
    autoFetch: true,
    useLocalCache: true,
    priorityFilter,
  });

  // Don't render anything if no notifications
  if (notifications.length === 0) {
    return null;
  }

  // Limit displayed notifications
  const displayedNotifications = notifications.slice(0, maxDisplay);

  return (
    <div className={`space-y-3 ${className}`}>
      {displayedNotifications.map((notification) => (
        <RemoteNotificationBanner
          key={notification.id}
          notification={notification}
          onDismiss={dismiss}
        />
      ))}

      {notifications.length > maxDisplay && (
        <p className="text-center text-gray-500 text-xs">
          还有 {notifications.length - maxDisplay} 条通知
        </p>
      )}
    </div>
  );
};
