/**
 * Hook for fetching and managing remote notifications
 */

import { useCallback, useEffect, useState } from 'react';
import {
  dismissNotification as dismissNotificationApi,
  getNotifications,
  type NotificationsResponse,
  type RemoteNotification,
} from '@/api/notifications';

/**
 * LocalStorage key for dismissed notifications
 * (Supplement to server-side storage for immediate UI response)
 */
const DISMISSED_STORAGE_KEY = 'zeroy_dismissed_notifications';

/**
 * LocalStorage key for cached notifications data
 */
const CACHE_DATA_KEY = 'zeroy_notifications_cache';

/**
 * LocalStorage key for last fetch timestamp
 */
const LAST_FETCH_KEY = 'zeroy_notifications_last_fetch';

/**
 * Cache duration in milliseconds (1 hour for localStorage supplement)
 */
const LOCAL_CACHE_DURATION = 60 * 60 * 1000;

/**
 * Get locally dismissed notification IDs
 */
function getLocalDismissed(): string[] {
  try {
    const stored = localStorage.getItem(DISMISSED_STORAGE_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch {
    return [];
  }
}

/**
 * Add a notification ID to local dismissed list
 */
function addLocalDismissed(id: string): void {
  try {
    const dismissed = getLocalDismissed();
    if (!dismissed.includes(id)) {
      dismissed.push(id);
      localStorage.setItem(DISMISSED_STORAGE_KEY, JSON.stringify(dismissed));
    }
  } catch {
    // Ignore storage errors
  }
}

/**
 * Check if we should fetch (based on local cache)
 */
function shouldFetch(): boolean {
  try {
    const lastFetch = localStorage.getItem(LAST_FETCH_KEY);
    if (!lastFetch) {
      return true;
    }
    const elapsed = Date.now() - Number.parseInt(lastFetch, 10);
    return elapsed > LOCAL_CACHE_DURATION;
  } catch {
    return true;
  }
}

/**
 * Get cached notifications data from localStorage
 */
function getCachedData(): NotificationsResponse | null {
  try {
    const cached = localStorage.getItem(CACHE_DATA_KEY);
    if (cached) {
      return JSON.parse(cached);
    }
  } catch {
    // Ignore parse errors
  }
  return null;
}

/**
 * Save notifications data to localStorage cache
 */
function setCachedData(data: NotificationsResponse): void {
  try {
    localStorage.setItem(CACHE_DATA_KEY, JSON.stringify(data));
    localStorage.setItem(LAST_FETCH_KEY, Date.now().toString());
  } catch {
    // Ignore storage errors
  }
}

interface UseRemoteNotificationsOptions {
  /**
   * Whether to auto-fetch on mount
   * @default true
   */
  autoFetch?: boolean;

  /**
   * Whether to respect local cache
   * @default true
   */
  useLocalCache?: boolean;

  /**
   * Filter by priority (only show these priorities)
   */
  priorityFilter?: ('high' | 'normal')[];
}

interface UseRemoteNotificationsResult {
  /**
   * Active notifications (filtered, not dismissed)
   */
  notifications: RemoteNotification[];

  /**
   * Whether notifications are loading
   */
  isLoading: boolean;

  /**
   * Error message if fetch failed
   */
  error: string | null;

  /**
   * Whether there are high priority notifications
   */
  hasHighPriority: boolean;

  /**
   * Total count of active notifications
   */
  count: number;

  /**
   * Dismiss a notification
   */
  dismiss: (id: string) => Promise<void>;

  /**
   * Manually refresh notifications
   */
  refresh: () => Promise<void>;
}

/**
 * Hook for fetching and managing remote notifications
 */
export function useRemoteNotifications(
  options: UseRemoteNotificationsOptions = {}
): UseRemoteNotificationsResult {
  const { autoFetch = true, useLocalCache = true, priorityFilter } = options;

  // Initialize state with cached data if available
  const [data, setData] = useState<NotificationsResponse | null>(() =>
    useLocalCache ? getCachedData() : null
  );
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [localDismissed, setLocalDismissed] = useState<string[]>(() =>
    getLocalDismissed()
  );

  /**
   * Fetch notifications from server
   */
  const fetchNotifications = useCallback(
    async (force = false) => {
      // Skip if using cache and not expired (unless forced)
      if (useLocalCache && !force && !shouldFetch()) {
        // Ensure we have cached data loaded
        const cached = getCachedData();
        if (cached && !data) {
          setData(cached);
        }
        return;
      }

      setIsLoading(true);
      setError(null);

      try {
        const response = await getNotifications();
        setData(response);
        // Save to localStorage cache
        if (useLocalCache) {
          setCachedData(response);
        }
      } catch (err) {
        const message =
          err instanceof Error ? err.message : 'Failed to fetch notifications';
        setError(message);
      } finally {
        setIsLoading(false);
      }
    },
    [useLocalCache, data]
  );

  /**
   * Dismiss a notification
   */
  const dismiss = useCallback(async (id: string) => {
    // Immediately update local state for responsive UI
    addLocalDismissed(id);
    setLocalDismissed((prev) => [...prev, id]);

    // Send dismiss request to server (fire and forget)
    try {
      await dismissNotificationApi(id);
    } catch {
      // Ignore errors - local dismissal is already applied
    }
  }, []);

  /**
   * Force refresh notifications
   */
  const refresh = useCallback(async () => {
    await fetchNotifications(true);
  }, [fetchNotifications]);

  // Auto-fetch on mount
  useEffect(() => {
    if (autoFetch) {
      fetchNotifications();
    }
  }, [autoFetch, fetchNotifications]);

  // Filter notifications
  const notifications =
    data?.notifications.filter((n) => {
      // Filter out locally dismissed
      if (localDismissed.includes(n.id)) {
        return false;
      }

      // Apply priority filter if specified
      if (priorityFilter && !priorityFilter.includes(n.priority)) {
        return false;
      }

      return true;
    }) ?? [];

  const hasHighPriority = notifications.some((n) => n.priority === 'high');

  return {
    notifications,
    isLoading,
    error,
    hasHighPriority,
    count: notifications.length,
    dismiss,
    refresh,
  };
}
