/**
 * Remote Notifications API Client
 */

import { apiClient } from './client';

/**
 * Notification priority levels
 */
export type NotificationPriority = 'high' | 'normal';

/**
 * Remote notification from server
 *
 * Note: Server handles version filtering and expiration.
 * Only active, matching notifications are returned.
 */
export interface RemoteNotification {
  id: string;
  priority: NotificationPriority;
  title?: string;
  message: string;
  created_at: string;
}

/**
 * Notifications API response
 */
export interface NotificationsResponse {
  notifications: RemoteNotification[];
  count: number;
  has_high_priority: boolean;
}

/**
 * Get notifications from server
 */
export function getNotifications(): Promise<NotificationsResponse> {
  return apiClient.get<NotificationsResponse>('/notifications');
}

/**
 * Dismiss a notification
 */
export function dismissNotification(
  notificationId: string
): Promise<{ dismissed: boolean }> {
  return apiClient.post<{ dismissed: boolean }>('/notifications/dismiss', {
    notification_id: notificationId,
  });
}

/**
 * Force refresh notifications cache (admin only)
 */
export function refreshNotifications(): Promise<NotificationsResponse> {
  return apiClient.post<NotificationsResponse>('/notifications/refresh');
}
