import type React from 'react';
import type { NotificationType } from './notification-provider';

interface NotificationProps {
  type: NotificationType;
  message: string;
  onDismiss: () => void;
}

const typeStyles: Record<NotificationType, string> = {
  success: 'bg-green-50 text-green-800 border-green-200',
  error: 'bg-red-50 text-red-800 border-red-200',
  warning: 'bg-yellow-50 text-yellow-800 border-yellow-200',
  info: 'bg-blue-50 text-blue-800 border-blue-200',
};

const icons: Record<NotificationType, string> = {
  success: '✓',
  error: '✕',
  warning: '⚠',
  info: 'ℹ',
};

export const Notification: React.FC<NotificationProps> = ({
  type,
  message,
  onDismiss,
}) => {
  return (
    <div
      className={`slide-in-from-right flex max-w-md animate-in items-center gap-3 rounded-lg border px-4 py-3 shadow-sm transition-all duration-300 ${typeStyles[type]} `}
    >
      <span className="flex-shrink-0 font-bold text-lg">{icons[type]}</span>
      <p className="!m-0 flex-1 break-words font-medium text-sm">{message}</p>
      <button
        aria-label="Dismiss"
        className="flex-shrink-0 text-lg transition-opacity hover:opacity-70"
        onClick={onDismiss}
        type="button"
      >
        ×
      </button>
    </div>
  );
};
